function Initialize-GeoraePlanArtifactRetentionProducerNativeType {
    if ('GeoraePlan.ArtifactRetentionProducer.PinnedEntry' -as [type]) { return }
    Add-Type -TypeDefinition @'
using System;
using System.ComponentModel;
using System.IO;
using System.Collections.Generic;
using System.Runtime.InteropServices;
using Microsoft.Win32.SafeHandles;
namespace GeoraePlan.ArtifactRetentionProducer {
 public sealed class Identity { public string FinalPath; public string VolumeSerialNumber; public string FileId; public uint Links; public bool IsDirectory; public bool IsReparsePoint; }
 public sealed class ChildEntry { public string Name; public PinnedEntry Entry; }
 public sealed class PinnedEntry : IDisposable {
  const uint ReadAttributes=0x80, ReadEa=8, ListDirectory=1, Delete=0x00010000, GenericRead=0x80000000, GenericWrite=0x40000000, Synchronize=0x00100000, ShareRead=1, ShareWrite=2, OpenExisting=3, BackupSemantics=0x02000000, DirectoryAttribute=0x10, ReparsePoint=0x400;
  const uint ObjCaseInsensitive=0x40, FileOpen=1, FileCreate=2, FileDirectoryFile=1, FileNonDirectoryFile=0x40, FileSynchronousIoNonAlert=0x20, FileOpenReparsePoint=0x00200000;
  SafeFileHandle handle; public Identity EntryIdentity { get; private set; }
  PinnedEntry(SafeFileHandle h, Identity i) { handle=h; EntryIdentity=i; }
  public static PinnedEntry Open(string path) { return OpenCore(path,ShareRead|ShareWrite); }
  public static PinnedEntry OpenStableDirectory(string path) { return OpenCore(path,ShareRead); }
  public static PinnedEntry OpenStableFile(string path) { return OpenCore(path,ShareRead); }
  public static PinnedEntry OpenExclusiveFile(string path) { return OpenCore(path,0); }
  static PinnedEntry OpenCore(string path,uint share) { uint a=GetFileAttributes(path); if(a==0xffffffff) throw new Win32Exception(Marshal.GetLastWin32Error()); bool d=(a&DirectoryAttribute)!=0; var h=CreateFile(path,d?ReadAttributes|ReadEa|ListDirectory:GenericRead,share,IntPtr.Zero,OpenExisting,d?BackupSemantics:0,IntPtr.Zero); if(h.IsInvalid) throw new Win32Exception(Marshal.GetLastWin32Error()); try { return new PinnedEntry(h, Read(h,path,a,d)); } catch { h.Dispose(); throw; } }
  public PinnedEntry CreateRelativeDirectory(string name, string expectedPath, byte[] securityDescriptor) { return OpenRelative(name,expectedPath,securityDescriptor,true,null,true,null,null); }
  public PinnedEntry CreateProvisionedRelativeDirectory(string name,string expectedPath,byte[] securityDescriptor,string eaName,byte[] eaValue) { return OpenRelative(name,expectedPath,securityDescriptor,true,null,true,eaName,eaValue); }
  public PinnedEntry CreateRelativeFile(string name, string expectedPath, byte[] bytes, byte[] securityDescriptor) { return OpenRelative(name,expectedPath,securityDescriptor,false,bytes,true,null,null); }
  public PinnedEntry OpenRelativeEntry(string name,string expectedPath,bool directory) { return OpenRelative(name,expectedPath,null,directory,null,false,null,null); }
  public PinnedEntry OpenRelativeFileForRepair(string name,string expectedPath) { return OpenRelative(name,expectedPath,null,false,null,false,null,null,true); }
  public PinnedEntry OpenRelativeEntryForCleanup(string name,string expectedPath,bool directory) { return OpenRelative(name,expectedPath,null,directory,null,false,null,null,false,true); }
  PinnedEntry OpenRelative(string name,string expectedPath,byte[] securityDescriptor,bool directory,byte[] bytes,bool create,string eaName,byte[] eaValue,bool repair=false,bool cleanup=false) {
   if(String.IsNullOrEmpty(name)||name=="."||name==".."||name.IndexOf('\\')>=0||name.IndexOf('/')>=0) throw new ArgumentException("A relative leaf name is required.");
   IntPtr nameBuffer=IntPtr.Zero,unicodeBuffer=IntPtr.Zero,objectBuffer=IntPtr.Zero,sdBuffer=IntPtr.Zero,eaBuffer=IntPtr.Zero; int eaLength=0; SafeFileHandle created=null;
   try {
    byte[] encoded=System.Text.Encoding.Unicode.GetBytes(name); nameBuffer=Marshal.AllocHGlobal(encoded.Length); Marshal.Copy(encoded,0,nameBuffer,encoded.Length);
    UNICODE_STRING unicode=new UNICODE_STRING(); unicode.Length=(ushort)encoded.Length; unicode.MaximumLength=(ushort)encoded.Length; unicode.Buffer=nameBuffer;
    unicodeBuffer=Marshal.AllocHGlobal(Marshal.SizeOf(typeof(UNICODE_STRING))); Marshal.StructureToPtr(unicode,unicodeBuffer,false);
    OBJECT_ATTRIBUTES oa=new OBJECT_ATTRIBUTES(); oa.Length=(uint)Marshal.SizeOf(typeof(OBJECT_ATTRIBUTES)); oa.RootDirectory=handle.DangerousGetHandle(); oa.ObjectName=unicodeBuffer; oa.Attributes=ObjCaseInsensitive;
    if(securityDescriptor!=null){sdBuffer=Marshal.AllocHGlobal(securityDescriptor.Length);Marshal.Copy(securityDescriptor,0,sdBuffer,securityDescriptor.Length);oa.SecurityDescriptor=sdBuffer;}
    if(eaName!=null||eaValue!=null){if(!create||String.IsNullOrWhiteSpace(eaName)||eaValue==null||eaValue.Length==0)throw new IOException("Relative create EA is invalid.");byte[] ea=BuildEaBuffer(eaName,eaValue);eaLength=ea.Length;eaBuffer=Marshal.AllocHGlobal(eaLength);Marshal.Copy(ea,0,eaBuffer,eaLength);}
    objectBuffer=Marshal.AllocHGlobal(Marshal.SizeOf(typeof(OBJECT_ATTRIBUTES))); Marshal.StructureToPtr(oa,objectBuffer,false);
     IO_STATUS_BLOCK io; uint access=Synchronize|ReadAttributes|(directory?(ListDirectory|ReadEa):(GenericRead|((create||repair)?GenericWrite:0)))|(cleanup?Delete:0); uint options=FileSynchronousIoNonAlert|FileOpenReparsePoint|(directory?FileDirectoryFile:FileNonDirectoryFile);
     int status=NtCreateFile(out created,access,objectBuffer,out io,IntPtr.Zero,0,repair?0:ShareRead,create?FileCreate:FileOpen,options,eaBuffer,(uint)eaLength);
    if(status<0) throw new Win32Exception((int)RtlNtStatusToDosError(status));
    if(!directory&&bytes!=null){uint written=0;if(bytes.Length>0&&!WriteFile(created,bytes,(uint)bytes.Length,out written,IntPtr.Zero))throw new Win32Exception(Marshal.GetLastWin32Error());if(written!=bytes.Length)throw new System.IO.IOException("Short metadata write.");if(!FlushFileBuffers(created))throw new Win32Exception(Marshal.GetLastWin32Error());}
    uint attrs=GetFileAttributes(expectedPath); if(attrs==0xffffffff)throw new Win32Exception(Marshal.GetLastWin32Error()); var result=new PinnedEntry(created,Read(created,expectedPath,attrs,directory)); created=null; return result;
   } finally { if(created!=null)created.Dispose();if(eaBuffer!=IntPtr.Zero)Marshal.FreeHGlobal(eaBuffer); if(objectBuffer!=IntPtr.Zero)Marshal.FreeHGlobal(objectBuffer);if(sdBuffer!=IntPtr.Zero)Marshal.FreeHGlobal(sdBuffer);if(unicodeBuffer!=IntPtr.Zero)Marshal.FreeHGlobal(unicodeBuffer);if(nameBuffer!=IntPtr.Zero)Marshal.FreeHGlobal(nameBuffer); }
  }
  static byte[] BuildEaBuffer(string name,byte[] value){byte[] n=System.Text.Encoding.ASCII.GetBytes(name);if(n.Length==0||n.Length>255||value.Length>65535)throw new IOException("Provisioning EA is outside bounds.");foreach(byte b in n)if(b<0x21||b>0x7e||b==(byte)'=')throw new IOException("Provisioning EA name is invalid.");byte[] x=new byte[8+n.Length+1+value.Length];x[5]=(byte)n.Length;x[6]=(byte)(value.Length&255);x[7]=(byte)((value.Length>>8)&255);Buffer.BlockCopy(n,0,x,8,n.Length);Buffer.BlockCopy(value,0,x,9+n.Length,value.Length);return x;}
  public byte[] ReadExtendedAttribute(string name){byte[] n=System.Text.Encoding.ASCII.GetBytes(name);IntPtr p=Marshal.AllocHGlobal(65536);try{IO_STATUS_BLOCK io;int status=NtQueryEaFile(handle,out io,p,65536,false,IntPtr.Zero,0,IntPtr.Zero,true);if(status!=0)throw new IOException("Provisioning EA cannot be read. NTSTATUS=0x"+status.ToString("X8"));int nl=Marshal.ReadByte(p,5),vl=(ushort)Marshal.ReadInt16(p,6);if(Marshal.ReadInt32(p,0)!=0||nl!=n.Length||vl<=0)throw new IOException("Provisioning EA is nonconforming.");byte[] actual=new byte[nl];Marshal.Copy(IntPtr.Add(p,8),actual,0,nl);for(int i=0;i<nl;i++)if(actual[i]!=n[i])throw new IOException("Provisioning EA name changed.");byte[] value=new byte[vl];Marshal.Copy(IntPtr.Add(p,9+nl),value,0,vl);return value;}finally{Marshal.FreeHGlobal(p);}}
  public byte[] ReadAllBytes() { if(EntryIdentity.IsDirectory) throw new InvalidOperationException("Directory bytes cannot be read."); SafeFileHandle duplicate; if(!DuplicateHandle(GetCurrentProcess(),handle,GetCurrentProcess(),out duplicate,0,false,2)) throw new Win32Exception(Marshal.GetLastWin32Error()); try { using(var stream=new System.IO.FileStream(duplicate,System.IO.FileAccess.Read)){duplicate=null;stream.Position=0;using(var memory=new System.IO.MemoryStream()){stream.CopyTo(memory);return memory.ToArray();}} } finally {if(duplicate!=null)duplicate.Dispose();} }
  public void CompleteExpectedBytes(byte[] expected) { byte[] actual=ReadAllBytes();if(actual.Length>expected.Length)throw new IOException("Pending metadata is longer than expected.");for(int i=0;i<actual.Length;i++)if(actual[i]!=expected[i])throw new IOException("Pending metadata is not an exact expected prefix.");long position;if(!SetFilePointerEx(handle,actual.Length,out position,0)||position!=actual.Length)throw new Win32Exception(Marshal.GetLastWin32Error());if(actual.Length<expected.Length){byte[] remaining=new byte[expected.Length-actual.Length];Buffer.BlockCopy(expected,actual.Length,remaining,0,remaining.Length);uint written;if(!WriteFile(handle,remaining,(uint)remaining.Length,out written,IntPtr.Zero)||written!=remaining.Length)throw new IOException("Pending metadata completion write failed.");}if(!FlushFileBuffers(handle))throw new Win32Exception(Marshal.GetLastWin32Error());byte[] complete=ReadAllBytes();if(complete.Length!=expected.Length)throw new IOException("Pending metadata completion length is invalid.");for(int i=0;i<complete.Length;i++)if(complete[i]!=expected[i])throw new IOException("Pending metadata completion bytes are invalid."); }
  public void MarkDelete() { SetDeleteDisposition(true); }
  public void ClearDelete() { SetDeleteDisposition(false); }
  void SetDeleteDisposition(bool delete) { IO_STATUS_BLOCK io; FILE_DISPOSITION_INFORMATION disposition=new FILE_DISPOSITION_INFORMATION();disposition.DeleteFile=delete;int status=NtSetInformationFile(handle,out io,ref disposition,(uint)Marshal.SizeOf(typeof(FILE_DISPOSITION_INFORMATION)),13);if(status<0)throw new IOException("Held entry delete disposition failed. NTSTATUS=0x"+status.ToString("X8")); }
  public ChildEntry[] EnumerateAndOpenChildren(string expectedDirectoryPath,string phase) { return EnumerateAndOpenChildrenCore(expectedDirectoryPath,null,null,phase,false); }
  public ChildEntry[] EnumerateAndOpenChildrenForCleanup(string expectedDirectoryPath) { return EnumerateAndOpenChildrenCore(expectedDirectoryPath,null,null,"cleanup",true); }
  public ChildEntry[] EnumerateAndOpenChildrenExceptHeld(string expectedDirectoryPath,string heldLeafName,PinnedEntry heldFile,string phase) { if(String.IsNullOrEmpty(heldLeafName)||heldLeafName.IndexOfAny(new[]{'\\','/'})>=0||heldFile==null||heldFile.EntryIdentity.IsDirectory||heldFile.EntryIdentity.IsReparsePoint||heldFile.EntryIdentity.Links!=1)throw new ArgumentException("Held leaf identity is invalid.");return EnumerateAndOpenChildrenCore(expectedDirectoryPath,heldLeafName,Convert.ToUInt64(heldFile.EntryIdentity.FileId,16),phase,false); }
  ChildEntry[] EnumerateAndOpenChildrenCore(string expectedDirectoryPath,string heldLeafName,ulong? heldFileId,string phase,bool cleanup) { if(!EntryIdentity.IsDirectory)throw new InvalidOperationException("Directory handle required.");if(phase!="parent"&&phase!="source"&&phase!="final-subset"&&phase!="cleanup")throw new ArgumentException("Enumeration phase is invalid.");var children=new List<ChildEntry>();IntPtr buffer=Marshal.AllocHGlobal(65536);bool restart=true;try{while(true){IO_STATUS_BLOCK io;int status=NtQueryDirectoryFile(handle,IntPtr.Zero,IntPtr.Zero,IntPtr.Zero,out io,buffer,65536,37,true,IntPtr.Zero,restart);restart=false;if(status==unchecked((int)0x80000006))break;if(status<0)throw new IOException("Held directory enumeration failed. phase="+phase+" NTSTATUS=0x"+status.ToString("X8"));int nameLength=Marshal.ReadInt32(buffer,60);string name=Marshal.PtrToStringUni(IntPtr.Add(buffer,104),nameLength/2);if(name=="."||name=="..")continue;uint attributes=(uint)Marshal.ReadInt32(buffer,56);bool directory=(attributes&DirectoryAttribute)!=0;ulong enumeratedId=(ulong)Marshal.ReadInt64(buffer,96);if(String.Equals(name,heldLeafName,StringComparison.Ordinal)){if(!heldFileId.HasValue||directory||enumeratedId!=heldFileId.Value)throw new IOException("Held coordinator enumeration identity is invalid.");children.Add(new ChildEntry{Name=name,Entry=null});continue;}PinnedEntry child=null;try{try{child=OpenRelative(name,System.IO.Path.Combine(expectedDirectoryPath,name),null,directory,null,false,null,null,false,cleanup);}catch(Win32Exception ex){throw new IOException("Held relative open failed. phase="+phase+" entry_kind="+(directory?"directory":"file")+" win32="+ex.NativeErrorCode,ex);}ulong openedId=Convert.ToUInt64(child.EntryIdentity.FileId,16);if(openedId!=enumeratedId)throw new IOException("Enumerated child identity changed before relative open. phase="+phase+" entry_kind="+(directory?"directory":"file"));children.Add(new ChildEntry{Name=name,Entry=child});child=null;}finally{if(child!=null)child.Dispose();}}return children.ToArray();}catch{foreach(var child in children)if(child.Entry!=null)child.Entry.Dispose();throw;}finally{Marshal.FreeHGlobal(buffer);} }
  public void Validate(string path) { var i=Read(handle,path,GetFileAttributes(path),EntryIdentity.IsDirectory); if(!String.Equals(i.FinalPath,path,StringComparison.OrdinalIgnoreCase)||i.VolumeSerialNumber!=EntryIdentity.VolumeSerialNumber||i.FileId!=EntryIdentity.FileId||i.Links!=EntryIdentity.Links||i.IsReparsePoint) throw new InvalidOperationException("Pinned filesystem entry changed."); }
  static Identity Read(SafeFileHandle h,string expected,uint attrs,bool directory) { BY_HANDLE_FILE_INFORMATION x; if(!GetFileInformationByHandle(h,out x)) throw new Win32Exception(Marshal.GetLastWin32Error()); char[] b=new char[32768]; uint n=GetFinalPathNameByHandle(h,b,(uint)b.Length,0); if(n==0||n>=b.Length) throw new Win32Exception(Marshal.GetLastWin32Error()); string p=new String(b,0,(int)n); if(p.StartsWith(@"\\?\UNC\",StringComparison.OrdinalIgnoreCase)) p=@"\\"+p.Substring(8); else if(p.StartsWith(@"\\?\",StringComparison.OrdinalIgnoreCase)) p=p.Substring(4); ulong id=((ulong)x.FileIndexHigh<<32)|x.FileIndexLow; return new Identity { FinalPath=p, VolumeSerialNumber=x.VolumeSerialNumber.ToString("X8"), FileId=id.ToString("X16"), Links=x.NumberOfLinks, IsDirectory=directory, IsReparsePoint=(x.FileAttributes&ReparsePoint)!=0}; }
  public void Dispose(){ if(handle!=null) handle.Dispose(); }
  [StructLayout(LayoutKind.Sequential)] struct FILETIME { public uint a,b; }
  [StructLayout(LayoutKind.Sequential)] struct BY_HANDLE_FILE_INFORMATION { public uint FileAttributes; public FILETIME CreationTime,LastAccessTime,LastWriteTime; public uint VolumeSerialNumber,FileSizeHigh,FileSizeLow,NumberOfLinks,FileIndexHigh,FileIndexLow; }
  [StructLayout(LayoutKind.Sequential)] struct UNICODE_STRING { public ushort Length,MaximumLength; public IntPtr Buffer; }
  [StructLayout(LayoutKind.Sequential)] struct OBJECT_ATTRIBUTES { public uint Length; public IntPtr RootDirectory,ObjectName; public uint Attributes; public IntPtr SecurityDescriptor,SecurityQualityOfService; }
  [StructLayout(LayoutKind.Sequential)] struct IO_STATUS_BLOCK { public IntPtr Status; public UIntPtr Information; }
  [StructLayout(LayoutKind.Sequential)] struct FILE_DISPOSITION_INFORMATION { [MarshalAs(UnmanagedType.I1)] public bool DeleteFile; }
  [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)] static extern SafeFileHandle CreateFile(string n,uint a,uint s,IntPtr q,uint c,uint f,IntPtr t);
  [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)] static extern uint GetFinalPathNameByHandle(SafeFileHandle h,[Out]char[] b,uint n,uint f);
  [DllImport("kernel32.dll",SetLastError=true)] static extern bool GetFileInformationByHandle(SafeFileHandle h,out BY_HANDLE_FILE_INFORMATION x);
  [DllImport("kernel32.dll",SetLastError=true)] static extern bool WriteFile(SafeFileHandle h,byte[] b,uint n,out uint w,IntPtr o);
  [DllImport("kernel32.dll",SetLastError=true)] static extern bool FlushFileBuffers(SafeFileHandle h);
  [DllImport("kernel32.dll",SetLastError=true)] static extern bool SetFilePointerEx(SafeFileHandle h,long distance,out long position,uint method);
  [DllImport("kernel32.dll")] static extern IntPtr GetCurrentProcess();
  [DllImport("kernel32.dll",SetLastError=true)] static extern bool DuplicateHandle(IntPtr sourceProcess,SafeFileHandle source,IntPtr targetProcess,out SafeFileHandle target,uint desiredAccess,bool inherit,uint options);
  [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)] static extern uint GetFileAttributes(string n);
  [DllImport("ntdll.dll")] static extern int NtCreateFile(out SafeFileHandle h,uint a,IntPtr o,out IO_STATUS_BLOCK i,IntPtr s,uint f,uint sh,uint d,uint opt,IntPtr e,uint l);
  [DllImport("ntdll.dll")] static extern int NtQueryEaFile(SafeFileHandle h,out IO_STATUS_BLOCK i,IntPtr b,uint l,bool single,IntPtr list,uint listLength,IntPtr index,bool restart);
  [DllImport("ntdll.dll")] static extern int NtQueryDirectoryFile(SafeFileHandle h,IntPtr e,IntPtr apc,IntPtr context,out IO_STATUS_BLOCK i,IntPtr b,uint l,int informationClass,bool single,IntPtr name,bool restart);
  [DllImport("ntdll.dll")] static extern int NtSetInformationFile(SafeFileHandle h,out IO_STATUS_BLOCK i,ref FILE_DISPOSITION_INFORMATION b,uint l,int informationClass);
  [DllImport("ntdll.dll")] static extern uint RtlNtStatusToDosError(int status);
 }
}
'@
