function Get-GeoraePlanArtifactRetentionNormalizedPath { param([Parameter(Mandatory=$true)][string]$Path) $p=[IO.Path]::GetFullPath($Path); if($p.Length -gt 3){$p=$p.TrimEnd('\')}; return $p }
function Test-GeoraePlanArtifactRetentionPathEquals { param([string]$Left,[string]$Right) return [string]::Equals((Get-GeoraePlanArtifactRetentionNormalizedPath $Left),(Get-GeoraePlanArtifactRetentionNormalizedPath $Right),[StringComparison]::OrdinalIgnoreCase) }
function Test-GeoraePlanArtifactRetentionPathInside { param([string]$Parent,[string]$Candidate) $p=(Get-GeoraePlanArtifactRetentionNormalizedPath $Parent)+'\'; return (Get-GeoraePlanArtifactRetentionNormalizedPath $Candidate).StartsWith($p,[StringComparison]::OrdinalIgnoreCase) }

function Open-GeoraePlanArtifactRetentionPinned { param([Parameter(Mandatory=$true)][string]$Path,[switch]$StableDirectory) Initialize-GeoraePlanArtifactRetentionProducerNativeType; $full=Get-GeoraePlanArtifactRetentionNormalizedPath $Path; if($StableDirectory){$entry=[GeoraePlan.ArtifactRetentionProducer.PinnedEntry]::OpenStableDirectory($full)}else{$entry=[GeoraePlan.ArtifactRetentionProducer.PinnedEntry]::Open($full)}; try { $i=$entry.EntryIdentity; if($i.IsReparsePoint -or (-not $i.IsDirectory -and $i.Links -ne 1) -or -not (Test-GeoraePlanArtifactRetentionPathEquals $i.FinalPath $full)){ throw 'Pinned artifact entry has an unsafe physical identity.' }; return [pscustomobject]@{ Path=$full; PhysicalPath=(Get-GeoraePlanArtifactRetentionNormalizedPath $i.FinalPath); VolumeSerialNumber=$i.VolumeSerialNumber; FileId=$i.FileId; NumberOfLinks=[uint32]$i.Links; IsDirectory=[bool]$i.IsDirectory; NativeHandle=$entry } } catch { $entry.Dispose(); throw } }
function Open-GeoraePlanArtifactRetentionStableFile { param([Parameter(Mandatory=$true)][string]$Path) Initialize-GeoraePlanArtifactRetentionProducerNativeType;$full=Get-GeoraePlanArtifactRetentionNormalizedPath $Path;$entry=[GeoraePlan.ArtifactRetentionProducer.PinnedEntry]::OpenStableFile($full);try{$i=$entry.EntryIdentity;if($i.IsDirectory -or $i.IsReparsePoint -or $i.Links -ne 1 -or -not(Test-GeoraePlanArtifactRetentionPathEquals $i.FinalPath $full)){throw 'Stable artifact file has an unsafe physical identity.'};return [pscustomobject]@{Path=$full;PhysicalPath=(Get-GeoraePlanArtifactRetentionNormalizedPath $i.FinalPath);VolumeSerialNumber=$i.VolumeSerialNumber;FileId=$i.FileId;NumberOfLinks=[uint32]$i.Links;IsDirectory=$false;NativeHandle=$entry}}catch{$entry.Dispose();throw} }
# Stable file and directory handles never grant delete sharing.
function Assert-GeoraePlanArtifactRetentionPinned { param([Parameter(Mandatory=$true)]$Pinned) $Pinned.NativeHandle.Validate($Pinned.Path); return $Pinned }
function Close-GeoraePlanArtifactRetentionPinned { param($Pinned) if($null -ne $Pinned -and $null -ne $Pinned.NativeHandle){$Pinned.NativeHandle.Dispose()} }
function Get-GeoraePlanArtifactRetentionIdentity { param([string]$Path,[switch]$Exclusive) $p=Open-GeoraePlanArtifactRetentionPinned $Path; try { return [pscustomobject]@{Path=$p.Path;PhysicalPath=$p.PhysicalPath;VolumeSerialNumber=$p.VolumeSerialNumber;FileId=$p.FileId;NumberOfLinks=$p.NumberOfLinks;IsDirectory=$p.IsDirectory} } finally { Close-GeoraePlanArtifactRetentionPinned $p } }

function Get-GeoraePlanArtifactRetentionAllowedSids { return @([Security.Principal.WindowsIdentity]::GetCurrent().User.Value,'S-1-5-18','S-1-5-32-544' | Select-Object -Unique) }
function Get-GeoraePlanArtifactRetentionPrivateAcl { $owner=[Security.Principal.WindowsIdentity]::GetCurrent().User;$acl=New-Object Security.AccessControl.DirectorySecurity;$acl.SetOwner($owner);$acl.SetAccessRuleProtection($true,$false);$inherit=[Security.AccessControl.InheritanceFlags]::ContainerInherit -bor [Security.AccessControl.InheritanceFlags]::ObjectInherit;foreach($sidText in Get-GeoraePlanArtifactRetentionAllowedSids){[void]$acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule([Security.Principal.SecurityIdentifier]$sidText,[Security.AccessControl.FileSystemRights]::FullControl,$inherit,[Security.AccessControl.PropagationFlags]::None,[Security.AccessControl.AccessControlType]::Allow)))};return $acl }
function Get-GeoraePlanArtifactRetentionPrivateAclBytes { $acl=Get-GeoraePlanArtifactRetentionPrivateAcl;$bytes=$acl.GetSecurityDescriptorBinaryForm();return ,$bytes }
function Get-GeoraePlanArtifactRetentionPrivateFileAcl { $owner=[Security.Principal.WindowsIdentity]::GetCurrent().User;$acl=New-Object Security.AccessControl.FileSecurity;$acl.SetOwner($owner);$acl.SetAccessRuleProtection($true,$false);foreach($sidText in Get-GeoraePlanArtifactRetentionAllowedSids){[void]$acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule([Security.Principal.SecurityIdentifier]$sidText,[Security.AccessControl.FileSystemRights]::FullControl,[Security.AccessControl.AccessControlType]::Allow)))};return $acl }
function Get-GeoraePlanArtifactRetentionPrivateFileAclBytes { $acl=Get-GeoraePlanArtifactRetentionPrivateFileAcl;return ,$acl.GetSecurityDescriptorBinaryForm() }
function Set-GeoraePlanArtifactRetentionPrivateAcl { param([string]$Path) $acl=Get-GeoraePlanArtifactRetentionPrivateAcl;Set-Acl -LiteralPath $Path -AclObject $acl -ErrorAction Stop;Assert-GeoraePlanArtifactRetentionPrivateAcl $Path }
function Assert-GeoraePlanArtifactRetentionPrivateAcl { param([string]$Path) $acl=Get-Acl -LiteralPath $Path -ErrorAction Stop; $current=[Security.Principal.WindowsIdentity]::GetCurrent().User.Value; $owner=$acl.GetOwner([Security.Principal.SecurityIdentifier]).Value; if($owner -cne $current -or -not $acl.AreAccessRulesProtected){throw 'Private artifact ACL owner/protection is invalid.'}; $expected=@(Get-GeoraePlanArtifactRetentionAllowedSids | Sort-Object); $actual=New-Object Collections.Generic.List[string]; foreach($rule in @($acl.Access)){ if($rule.IsInherited -or $rule.AccessControlType -ne [Security.AccessControl.AccessControlType]::Allow -or $rule.FileSystemRights -ne [Security.AccessControl.FileSystemRights]::FullControl){throw 'Private artifact ACL has an inherited, deny, or non-full-control entry.'}; $sid=$rule.IdentityReference.Translate([Security.Principal.SecurityIdentifier]).Value; $actual.Add($sid) }; $actual=@($actual | Sort-Object); if($actual.Count -ne $expected.Count -or (@(Compare-Object $actual $expected).Count -ne 0)){throw 'Private artifact ACL allowlist is not exact.'} }
function Assert-GeoraePlanArtifactRetentionPrivateFileAcl { param([string]$Path) $acl=Get-Acl -LiteralPath $Path -ErrorAction Stop;$current=[Security.Principal.WindowsIdentity]::GetCurrent().User.Value;$owner=$acl.GetOwner([Security.Principal.SecurityIdentifier]).Value;if($owner -cne $current -or -not $acl.AreAccessRulesProtected){throw 'Private artifact file ACL owner/protection is invalid.'};$expected=@(Get-GeoraePlanArtifactRetentionAllowedSids|Sort-Object);$actual=New-Object Collections.Generic.List[string];foreach($rule in @($acl.Access)){if($rule.IsInherited -or $rule.AccessControlType -ne [Security.AccessControl.AccessControlType]::Allow -or $rule.FileSystemRights -ne [Security.AccessControl.FileSystemRights]::FullControl -or $rule.InheritanceFlags -ne [Security.AccessControl.InheritanceFlags]::None){throw 'Private artifact file ACL is not exact.'};$actual.Add($rule.IdentityReference.Translate([Security.Principal.SecurityIdentifier]).Value)};$actual=@($actual|Sort-Object);if($actual.Count -ne $expected.Count -or @(Compare-Object $actual $expected).Count -ne 0){throw 'Private artifact file ACL allowlist is not exact.'} }

