function New-GeoraePlanArtifactRetentionRelativeDirectory { param($Parent,[string]$Name) $path=Join-Path $Parent.Path $Name;$native=$Parent.NativeHandle.CreateRelativeDirectory($Name,$path,(Get-GeoraePlanArtifactRetentionPrivateAclBytes));try{$i=$native.EntryIdentity;return [pscustomobject]@{Path=$path;PhysicalPath=(Get-GeoraePlanArtifactRetentionNormalizedPath $i.FinalPath);VolumeSerialNumber=$i.VolumeSerialNumber;FileId=$i.FileId;NumberOfLinks=[uint32]$i.Links;IsDirectory=$true;NativeHandle=$native}}catch{$native.Dispose();throw} }
