function Get-GeoraePlanArtifactRetentionHeldFinalConsumerTree { param($PinnedFinal,$ExpectedEntries) $items=New-Object Collections.Generic.List[object];$handles=New-Object Collections.Generic.List[object];try{Add-GeoraePlanArtifactRetentionFinalConsumerTree $PinnedFinal '' $items $handles;$actual=@($items.ToArray()|Sort-Object {$_.relativePath});if((ConvertTo-GeoraePlanArtifactRetentionStrictJson $actual) -cne (ConvertTo-GeoraePlanArtifactRetentionStrictJson @($ExpectedEntries))){throw 'Completed artifact tree differs from the exact consumer entries.'};return [pscustomobject]@{Items=$actual;Handles=$handles}}catch{for($i=$handles.Count-1;$i-ge0;$i--){Close-GeoraePlanArtifactRetentionPinned $handles[$i]};throw} }
function Add-GeoraePlanArtifactRetentionRelativePlan { param($PinnedDirectory,[string]$Prefix,$Items,$Handles,[switch]$IncludeAll) Assert-GeoraePlanArtifactRetentionPinned $PinnedDirectory|Out-Null;$children=New-Object Collections.Generic.List[object];try{foreach($record in @($PinnedDirectory.NativeHandle.EnumerateAndOpenChildren($PinnedDirectory.Path,'source'))){$child=ConvertFrom-GeoraePlanArtifactRetentionNativeChild $PinnedDirectory $record;[void]$children.Add([pscustomobject]@{Name=$record.Name;Pinned=$child});[void]$Handles.Add($child)};foreach($entry in $children){if(-not$IncludeAll -and $entry.Name -eq '.georaeplan-producer-stage.json' -and [string]::IsNullOrEmpty($Prefix)){continue};$child=$entry.Pinned;$relative=if([string]::IsNullOrEmpty($Prefix)){$entry.Name}else{$Prefix+'/'+$entry.Name};if($child.IsDirectory){$Items.Add([pscustomobject][ordered]@{relativePath=$relative;kind='directory';length=[int64]0;sha256=$null;SourcePinned=$child});Add-GeoraePlanArtifactRetentionRelativePlan $child $relative $Items $Handles -IncludeAll:$IncludeAll}else{$bytes=Read-GeoraePlanArtifactRetentionPinnedBytes $child;$Items.Add([pscustomobject][ordered]@{relativePath=$relative;kind='file';length=[int64]$bytes.Length;sha256=(Get-GeoraePlanArtifactRetentionSha256 $bytes);SourcePinned=$child})}}}catch{throw};Assert-GeoraePlanArtifactRetentionPinned $PinnedDirectory|Out-Null }
function Get-GeoraePlanArtifactRetentionMaterializationPlan { param($PinnedSource) $items=New-Object Collections.Generic.List[object];$handles=New-Object Collections.Generic.List[object];try{Add-GeoraePlanArtifactRetentionRelativePlan $PinnedSource '' $items $handles;$sorted=@($items.ToArray()|Sort-Object {$_.relativePath});return [pscustomobject]@{Items=$sorted;Handles=$handles}}catch{for($i=$handles.Count-1;$i -ge 0;$i--){Close-GeoraePlanArtifactRetentionPinned $handles[$i]};throw} }
function Get-GeoraePlanArtifactRetentionExactClosurePlan { param($PinnedSource) $items=New-Object Collections.Generic.List[object];$handles=New-Object Collections.Generic.List[object];try{Add-GeoraePlanArtifactRetentionRelativePlan $PinnedSource '' $items $handles -IncludeAll;$sorted=@($items.ToArray()|Sort-Object {$_.relativePath});return [pscustomobject]@{Items=$sorted;Handles=$handles}}catch{for($i=$handles.Count-1;$i -ge 0;$i--){Close-GeoraePlanArtifactRetentionPinned $handles[$i]};throw} }
function Close-GeoraePlanArtifactRetentionHeldTree { param($HeldTree) if($null -ne $HeldTree){for($i=$HeldTree.Handles.Count-1;$i -ge 0;$i--){Close-GeoraePlanArtifactRetentionPinned $HeldTree.Handles[$i]}} }
function Get-GeoraePlanArtifactRetentionJournalPlan { param($Plan) return @($Plan|ForEach-Object{[ordered]@{relativePath=[string]$_.relativePath;kind=[string]$_.kind;length=[int64]$_.length;sha256=$_.sha256;volumeSerialNumber=[string]$_.SourcePinned.VolumeSerialNumber;fileId=[string]$_.SourcePinned.FileId}}) }
function Assert-GeoraePlanArtifactRetentionMaterializationPlan {
 param($PinnedSource,$ExpectedPlan)
 foreach($item in @($ExpectedPlan)){Assert-GeoraePlanArtifactRetentionPinned $item.SourcePinned|Out-Null;if($item.kind -ceq 'file'){$bytes=Read-GeoraePlanArtifactRetentionPinnedBytes $item.SourcePinned;if($bytes.Length -ne [int64]$item.length -or (Get-GeoraePlanArtifactRetentionSha256 $bytes) -cne [string]$item.sha256){throw 'Held artifact source file changed.'}}}
 $fresh=$null;try{$fresh=Get-GeoraePlanArtifactRetentionMaterializationPlan $PinnedSource;if((ConvertTo-GeoraePlanArtifactRetentionStrictJson (Get-GeoraePlanArtifactRetentionJournalPlan $fresh.Items)) -cne (ConvertTo-GeoraePlanArtifactRetentionStrictJson (Get-GeoraePlanArtifactRetentionJournalPlan $ExpectedPlan))){throw 'Artifact source changed after finalize journal creation.'}}finally{Close-GeoraePlanArtifactRetentionHeldTree $fresh}
}
function Assert-GeoraePlanArtifactRetentionExactClosurePlan {
 param($PinnedSource,$ExpectedPlan)
 foreach($item in @($ExpectedPlan)){Assert-GeoraePlanArtifactRetentionPinned $item.SourcePinned|Out-Null;if($item.kind -ceq 'file'){$bytes=Read-GeoraePlanArtifactRetentionPinnedBytes $item.SourcePinned;if($bytes.Length -ne [int64]$item.length -or (Get-GeoraePlanArtifactRetentionSha256 $bytes) -cne [string]$item.sha256){throw 'Held test dependency file changed.'}}}
 $fresh=$null;try{$fresh=Get-GeoraePlanArtifactRetentionExactClosurePlan $PinnedSource;if((ConvertTo-GeoraePlanArtifactRetentionStrictJson (Get-GeoraePlanArtifactRetentionJournalPlan $fresh.Items)) -cne (ConvertTo-GeoraePlanArtifactRetentionStrictJson (Get-GeoraePlanArtifactRetentionJournalPlan $ExpectedPlan))){throw 'Test execution dependency tree changed.'}}finally{Close-GeoraePlanArtifactRetentionHeldTree $fresh}
}
function Get-GeoraePlanArtifactRetentionPlanItem { param($Plan,[string]$RelativePath) foreach($item in @($Plan)){if(([string]$item.relativePath) -ceq $RelativePath){return $item}};return $null }
function Assert-GeoraePlanArtifactRetentionFinalSubsetDirectory { param($PinnedDirectory,[string]$Prefix,$Plan,[string[]]$MetadataNames) $heldChildren=New-Object Collections.Generic.List[object];try{foreach($record in @($PinnedDirectory.NativeHandle.EnumerateAndOpenChildren($PinnedDirectory.Path,'final-subset'))){$held=ConvertFrom-GeoraePlanArtifactRetentionNativeChild $PinnedDirectory $record;[void]$heldChildren.Add([pscustomobject]@{Name=$record.Name;Pinned=$held})};foreach($entry in $heldChildren){$held=$entry.Pinned;$relative=if([string]::IsNullOrEmpty($Prefix)){$entry.Name}else{$Prefix+'/'+$entry.Name};if(-not$held.IsDirectory -and [string]::IsNullOrEmpty($Prefix) -and $relative -in $MetadataNames){Assert-GeoraePlanArtifactRetentionPrivateFileAcl $held.Path;continue};$expected=Get-GeoraePlanArtifactRetentionPlanItem $Plan $relative;if($null -eq $expected){throw 'Partial artifact contains an unknown entry.'};if($held.IsDirectory){if($expected.kind -cne 'directory'){throw 'Partial artifact entry type is invalid.'};Assert-GeoraePlanArtifactRetentionPrivateAcl $held.Path;Assert-GeoraePlanArtifactRetentionFinalSubsetDirectory $held $relative $Plan $MetadataNames}else{if($expected.kind -cne 'file'){throw 'Partial artifact entry type is invalid.'};Assert-GeoraePlanArtifactRetentionPrivateFileAcl $held.Path;$bytes=Read-GeoraePlanArtifactRetentionPinnedBytes $held;$sourceBytes=Read-GeoraePlanArtifactRetentionPinnedBytes $expected.SourcePinned;if($bytes.Length -gt [int64]$expected.length){throw 'Partial artifact file is longer than expected.'};for($prefixIndex=0;$prefixIndex -lt $bytes.Length;$prefixIndex++){if($bytes[$prefixIndex] -ne $sourceBytes[$prefixIndex]){throw 'Partial artifact file is not an exact expected prefix.'}}}}}finally{for($i=$heldChildren.Count-1;$i -ge 0;$i--){Close-GeoraePlanArtifactRetentionPinned $heldChildren[$i].Pinned}} }
function Assert-GeoraePlanArtifactRetentionFinalSubset { param($PinnedFinal,$Plan,[string[]]$MetadataNames) Assert-GeoraePlanArtifactRetentionPinned $PinnedFinal|Out-Null;Assert-GeoraePlanArtifactRetentionFinalSubsetDirectory $PinnedFinal '' $Plan $MetadataNames;Assert-GeoraePlanArtifactRetentionPinned $PinnedFinal|Out-Null }
function Copy-GeoraePlanArtifactRetentionPlanItem {
 param($PinnedFinal,$Item,$DestinationLeases,[string]$TestFaultInjection)
 $segments=@(([string]$Item.relativePath).Split('/'))
 if($segments.Count -eq 0 -or @($segments|Where-Object{[string]::IsNullOrWhiteSpace($_) -or $_ -eq '.' -or $_ -eq '..'}).Count -ne 0){throw 'Materialization plan contains an unsafe relative path.'}
 $current=$PinnedFinal;$opened=New-Object Collections.Generic.List[object]
 try{
  for($index=0;$index -lt $segments.Count-1;$index++){
   $childPath=Join-Path $current.Path $segments[$index]
   if(Test-Path -LiteralPath $childPath){$child=Open-GeoraePlanArtifactRetentionRelativeEntry $current $segments[$index] $true;Assert-GeoraePlanArtifactRetentionPrivateAcl $childPath}
   else{$child=New-GeoraePlanArtifactRetentionRelativeDirectory $current $segments[$index]}
   $opened.Add($child);$DestinationLeases.Add($child);$current=$child
  }
  $leaf=$segments[$segments.Count-1];$destination=Join-Path $current.Path $leaf
  if($Item.kind -ceq 'directory'){
   if(Test-Path -LiteralPath $destination){$existing=Open-GeoraePlanArtifactRetentionRelativeEntry $current $leaf $true;Assert-GeoraePlanArtifactRetentionPrivateAcl $destination;$DestinationLeases.Add($existing)}
   else{$created=New-GeoraePlanArtifactRetentionRelativeDirectory $current $leaf;$DestinationLeases.Add($created)}
  } elseif($Item.kind -ceq 'file') {
   $bytes=Read-GeoraePlanArtifactRetentionPinnedBytes $Item.SourcePinned
   if($bytes.Length -ne [int64]$Item.length -or (Get-GeoraePlanArtifactRetentionSha256 $bytes) -cne [string]$Item.sha256){throw 'Artifact source file changed during materialization.'}
    $payloadPartial=if($TestFaultInjection -eq 'PartialPayloadOneByte' -and -not(Test-Path -LiteralPath $destination)){1}else{-1};$ensured=Write-GeoraePlanArtifactRetentionRelativeCreateNewBytes $current $leaf $bytes $payloadPartial;$DestinationLeases.Add($ensured)
  } else {throw 'Materialization plan kind is invalid.'}
 } finally { }
}
function Get-GeoraePlanArtifactRetentionFinalMetadataNames { return @($script:GeoraePlanArtifactRetentionOwnerFileName,$script:GeoraePlanArtifactRetentionProducerManifestFileName,$script:GeoraePlanArtifactRetentionCompletionFileName) }
function Invoke-GeoraePlanArtifactRetentionMaterialization { param($PinnedSource,$PinnedFinal,$Plan,$DestinationLeases,[string]$TestFaultInjection) Assert-GeoraePlanArtifactRetentionFinalSubset $PinnedFinal $Plan @(Get-GeoraePlanArtifactRetentionFinalMetadataNames);foreach($item in @($Plan)){Copy-GeoraePlanArtifactRetentionPlanItem $PinnedFinal $item $DestinationLeases $TestFaultInjection};Assert-GeoraePlanArtifactRetentionMaterializationPlan $PinnedSource $Plan;Assert-GeoraePlanArtifactRetentionFinalSubset $PinnedFinal $Plan @(Get-GeoraePlanArtifactRetentionFinalMetadataNames) }
function Test-GeoraePlanArtifactRetentionFault { param([string]$Name,[string]$Requested) if($Requested -eq $Name){if($env:GEORAEPLAN_ARTIFACT_PRODUCER_TEST_MODE -ne '1'){throw 'Fault injection is test-mode only.'};throw "Injected producer fault: $Name"} }
function Invoke-GeoraePlanArtifactRetentionTestStageSwap { param([string]$StagePath,$PinnedStage,[string]$Destination,[string]$Requested) if($Requested -ne 'SwapStageNameBeforePublish'){return $false};if($env:GEORAEPLAN_ARTIFACT_PRODUCER_TEST_MODE -ne '1'){throw 'Fault injection is test-mode only.'};$moved=$StagePath+'.swapped';$command="[IO.Directory]::Move('"+$StagePath.Replace("'","''")+"','"+$moved.Replace("'","''")+"')";$encoded=[Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($command));$process=Start-Process -FilePath "$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe" -ArgumentList @('-NoProfile','-EncodedCommand',$encoded) -WindowStyle Hidden -Wait -PassThru;if($process.ExitCode -eq 0 -or (Test-Path -LiteralPath $moved)){throw 'External stage name substitution unexpectedly succeeded.'};Assert-GeoraePlanArtifactRetentionPinned $PinnedStage|Out-Null;return $true }

function Get-GeoraePlanArtifactRetentionConsumerReservedNames {
 return @('.georaeplan-runtime-ready','.georaeplan-runtime-invalid','.georaeplan-prepare.lock','.georaeplan-prepare-gate.lock','.georaeplan-artifact.active.lease','.georaeplan-artifact-process.json','Run-All.cmd','Run-All.ps1','Run-App.cmd','Run-Server.cmd','Launch-Test-App.vbs')
}
function Assert-GeoraePlanArtifactRetentionConsumerMetadataBytes { param([byte[]]$Bytes) if($null -eq $Bytes -or $Bytes.Length -gt 65536){throw 'Artifact completion metadata exceeds the consumer limit.'} }
function Assert-GeoraePlanArtifactRetentionConsumerPlan {
 param($Plan)
 $reserved=@(Get-GeoraePlanArtifactRetentionConsumerReservedNames);$seen=New-Object 'Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
 foreach($item in @($Plan)){
  if($null -eq $item -or $item.kind -notin @('file','directory')){throw 'Artifact plan kind is outside the consumer contract.'}
  $relative=[string]$item.relativePath
  if([string]::IsNullOrWhiteSpace($relative) -or $relative.Contains('\') -or $relative.StartsWith('/') -or $relative.EndsWith('/')){throw 'Artifact plan relative path is outside the consumer contract.'}
  if(-not$seen.Add($relative)){throw 'Artifact plan contains a case-insensitive duplicate.'}
  $segments=$relative.Split('/')
  if(@($segments|Where-Object{[string]::IsNullOrWhiteSpace($_) -or $_ -in @('.','..')}).Count -ne 0){throw 'Artifact plan contains an unsafe segment.'}
  foreach($segment in $segments){if($segment -iin $reserved -or $segment -imatch '(?:\.pid|\.lock|\.lck|\.lease)$'){throw 'Artifact plan contains a consumer-reserved entry.'}}
  if($segments.Count -eq 1 -and $segments[0] -iin @($script:GeoraePlanArtifactRetentionOwnerFileName,$script:GeoraePlanArtifactRetentionCompletionFileName,$script:GeoraePlanArtifactRetentionProducerManifestFileName)){throw 'Artifact plan collides with root metadata.'}
 }
}
function Get-GeoraePlanArtifactRetentionPlanItemExact { param($Plan,[string]$RelativePath) foreach($item in @($Plan)){if(([string]$item.relativePath) -ceq $RelativePath){return $item}};return $null }
function Add-GeoraePlanArtifactRetentionHeldStageCleanupDirectory {
 param($PinnedDirectory,[string]$Prefix,$JournalPlan,[string]$StageMarkerSha256,[string]$StageMarkerVolumeSerialNumber,[string]$StageMarkerFileId,$DeleteOrder,[switch]$AllowMissing)
 $records=New-Object Collections.Generic.List[object]
 try{
  foreach($record in @($PinnedDirectory.NativeHandle.EnumerateAndOpenChildrenForCleanup($PinnedDirectory.Path))){$child=ConvertFrom-GeoraePlanArtifactRetentionNativeChild $PinnedDirectory $record;[void]$records.Add([pscustomobject]@{Name=$record.Name;Pinned=$child})}
  foreach($record in $records){
   $child=$record.Pinned;$relative=if([string]::IsNullOrEmpty($Prefix)){$record.Name}else{$Prefix+'/'+$record.Name}
   if([string]::IsNullOrEmpty($Prefix) -and $record.Name -ceq '.georaeplan-producer-stage.json'){
    if($child.IsDirectory -or $child.VolumeSerialNumber -ine $StageMarkerVolumeSerialNumber -or $child.FileId -ine $StageMarkerFileId){throw 'Stage marker cleanup identity is invalid.'}
    Assert-GeoraePlanArtifactRetentionPrivateFileAcl $child.Path
    if((Get-GeoraePlanArtifactRetentionSha256 (Read-GeoraePlanArtifactRetentionPinnedBytes $child)) -ine $StageMarkerSha256){throw 'Stage marker cleanup bytes changed.'}
    continue
   }
   $expected=Get-GeoraePlanArtifactRetentionPlanItemExact $JournalPlan $relative
   if($null -eq $expected){throw 'Stage cleanup found an unknown entry.'}
   if($child.IsDirectory -ne ($expected.kind -ceq 'directory') -or $child.VolumeSerialNumber -ine [string]$expected.volumeSerialNumber -or $child.FileId -ine [string]$expected.fileId){throw 'Stage cleanup entry identity is invalid.'}
   if(-not$child.IsDirectory){$bytes=Read-GeoraePlanArtifactRetentionPinnedBytes $child;if($bytes.Length -ne [int64]$expected.length -or (Get-GeoraePlanArtifactRetentionSha256 $bytes) -ine [string]$expected.sha256){throw 'Stage cleanup file bytes changed.'}}
  }
  if(-not$AllowMissing){
   $actual=@($records|ForEach-Object{if([string]::IsNullOrEmpty($Prefix)){$_.Name}else{$Prefix+'/'+$_.Name}}|Where-Object{$_ -cne '.georaeplan-producer-stage.json'}|Sort-Object)
   $wanted=@($JournalPlan|Where-Object{if([string]::IsNullOrEmpty($Prefix)){([string]$_.relativePath).IndexOf('/') -lt 0}else{([string]$_.relativePath).StartsWith($Prefix+'/',[StringComparison]::Ordinal) -and ([string]$_.relativePath).Substring($Prefix.Length+1).IndexOf('/') -lt 0}}|ForEach-Object{$_.relativePath}|Sort-Object)
   if($actual.Count -ne $wanted.Count -or @(Compare-Object $actual $wanted).Count -ne 0){throw 'Stage cleanup exact child set is incomplete.'}
  }
  foreach($record in @($records|Where-Object{-not$_.Pinned.IsDirectory})){[void]$DeleteOrder.Add($record.Pinned);$record.Pinned=$null}
  foreach($record in @($records|Where-Object{$null -ne $_.Pinned -and $_.Pinned.IsDirectory})){$relative=if([string]::IsNullOrEmpty($Prefix)){$record.Name}else{$Prefix+'/'+$record.Name};Add-GeoraePlanArtifactRetentionHeldStageCleanupDirectory $record.Pinned $relative $JournalPlan $StageMarkerSha256 $StageMarkerVolumeSerialNumber $StageMarkerFileId $DeleteOrder -AllowMissing:$AllowMissing;[void]$DeleteOrder.Add($record.Pinned);$record.Pinned=$null}
 }finally{foreach($record in $records){if($null -ne $record.Pinned){Close-GeoraePlanArtifactRetentionPinned $record.Pinned}}}
}
function New-GeoraePlanArtifactRetentionHeldStageCleanupPlan {
 param($Parent,$ExclusiveCoordinator,[string]$StageName,$StageIdentity,$JournalPlan,[string]$StageMarkerSha256,[string]$StageMarkerVolumeSerialNumber,[string]$StageMarkerFileId,[switch]$AllowMissing)
 $stage=$null;$order=New-Object Collections.Generic.List[object]
 try{
  try{$stage=Open-GeoraePlanArtifactRetentionRelativeEntryForCleanup $Parent.Identity $StageName $true}catch{if($AllowMissing){Assert-GeoraePlanArtifactRetentionParentChildSet $Parent.Identity $ExclusiveCoordinator;return [pscustomobject]@{Entries=$order;Missing=$true}};throw}
  if($stage.VolumeSerialNumber -ine [string]$StageIdentity.VolumeSerialNumber -or $stage.FileId -ine [string]$StageIdentity.FileId){throw 'Stage cleanup root identity is invalid.'}
  Assert-GeoraePlanArtifactRetentionPrivateAcl $stage.Path
  $token=$stage.NativeHandle.ReadExtendedAttribute($script:GeoraePlanArtifactRetentionStageEaName);if((Get-GeoraePlanArtifactRetentionSha256 $token) -ine [string]$StageIdentity.TokenSha256){throw 'Stage cleanup provisioning token changed.'}
  Add-GeoraePlanArtifactRetentionHeldStageCleanupDirectory $stage '' $JournalPlan $StageMarkerSha256 $StageMarkerVolumeSerialNumber $StageMarkerFileId $order -AllowMissing:$AllowMissing
  [void]$order.Add($stage);$stage=$null
  return [pscustomobject]@{Entries=$order;Missing=$false}
 }catch{for($i=$order.Count-1;$i-ge0;$i--){Close-GeoraePlanArtifactRetentionPinned $order[$i]};throw}finally{Close-GeoraePlanArtifactRetentionPinned $stage}
}
function Close-GeoraePlanArtifactRetentionHeldStageCleanupPlan {
 param($Plan,[switch]$Commit,[string]$Fault='')
 if($null -eq $Plan){return}
 if(-not$Commit){for($i=0;$i-lt$Plan.Entries.Count;$i++){Close-GeoraePlanArtifactRetentionPinned $Plan.Entries[$i]};$Plan.Entries.Clear();return}
 $committed=0
 try{foreach($entry in @($Plan.Entries|Where-Object{-not$_.IsDirectory})){$entry.NativeHandle.MarkDelete();Close-GeoraePlanArtifactRetentionPinned $entry;$committed++;if($committed-eq1-and$Fault-ceq'FailAfterFirstCleanupCommit'){throw 'Injected failure after first cleanup commit.'}};foreach($entry in @($Plan.Entries|Where-Object{$_.IsDirectory})){$entry.NativeHandle.MarkDelete();Close-GeoraePlanArtifactRetentionPinned $entry}}finally{foreach($entry in $Plan.Entries){Close-GeoraePlanArtifactRetentionPinned $entry};$Plan.Entries.Clear()}
}
